package com.example.bodega.producto.controller;
import com.example.bodega.common.dto.EstadoRequest; import com.example.bodega.producto.dto.*; import com.example.bodega.producto.service.ProductoService; import com.example.bodega.security.SecurityUser;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/productos") @RequiredArgsConstructor
public class ProductoController { private final ProductoService service; @GetMapping public Page<ProductoResponse> listar(@RequestParam(required=false) String nombre,@RequestParam(required=false) Long categoriaId,@RequestParam(required=false) Boolean activo,@PageableDefault(size=20,sort="nombre") Pageable pageable){return service.listar(nombre,categoriaId,activo,pageable);}@GetMapping("/{id}") public ProductoResponse obtener(@PathVariable Long id){return service.obtener(id);}@GetMapping("/barcode/{codigo}") public ProductoResponse barcode(@PathVariable String codigo){return service.porCodigo(codigo);}@PostMapping @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<ProductoResponse> crear(@Valid @RequestBody ProductoRequest r,@AuthenticationPrincipal SecurityUser u){return ResponseEntity.status(HttpStatus.CREATED).body(service.crear(r,u.id()));}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ProductoResponse actualizar(@PathVariable Long id,@Valid @RequestBody ProductoRequest r){return service.actualizar(id,r);}@PatchMapping("/{id}/estado") @PreAuthorize("hasRole('ADMIN')") public ProductoResponse estado(@PathVariable Long id,@Valid @RequestBody EstadoRequest r){return service.cambiarEstado(id,r.activo());}@PatchMapping("/{id}/desactivar") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void desactivar(@PathVariable Long id){service.desactivar(id);} }
